// ---------- Initialization and resilient event binding ----------
function init(){
 document.title='منصة الذكاء الاصطناعي والنظم الخبيرة';$('#todayLabel').textContent=new Date().toLocaleDateString('ar-EG',{weekday:'long',day:'numeric',month:'long'});document.body.classList.toggle('dark',state.theme==='dark');
 renderDashboard();renderLibrary();renderBank();buildDocumentSettingsUI();addProjectIdentity();
 const bankChapters=[...new Set(COURSE_QUESTIONS.map(q=>String(q.ch)))].sort((a,b)=>Number(a)-Number(b));$('#bankChapter').innerHTML='<option value="all">كل فصول المقرر</option>'+bankChapters.map(n=>`<option value="${n}">الفصل ${n}</option>`).join('');
 const chapterOptions=bankChapters.map(n=>`<option value="${n}">الفصل ${n}</option>`).join('');
 const addSelect=(host,id,label,options)=>{if($('#'+id))return;const wrap=document.createElement('label');wrap.textContent=label;const select=document.createElement('select');select.id=id;select.innerHTML=options;wrap.append(select);host.append(wrap);};
 addSelect($('#page-practice .form-grid'),'practiceChapter','الفصل','<option value="all">كل الفصول</option>'+chapterOptions);
 addSelect($('#page-practice .form-grid'),'practiceMode','نوع التدريب','<option value="all">كل الأسئلة</option><option value="wrong">الأسئلة التي أخطأت فيها</option><option value="unmastered">الأسئلة التي لم تتقنها بعد</option>');
 addSelect($('#page-exam .form-grid'),'examChapter','الفصل','<option value="all">اختبار شامل</option>'+chapterOptions);
 addSelect($('#page-exam .form-grid'),'examType','نوع السؤال','<option value="all">كل الأنواع</option><option value="mcq">اختيار من متعدد</option><option value="tf">صح أو خطأ</option>');
 $('#practiceAvailable').textContent=`عدد الأسئلة المطابقة للاختيارات الحالية: ${COURSE_QUESTIONS.length}`;
 // All navigation actions are delegated once; hidden/removed assistant UI has no listeners.
 $('#mainNav').addEventListener('click',e=>{const button=e.target.closest('.nav-link[data-page]');if(button)setPage(button.dataset.page);});
 document.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go)setPage(go.dataset.go);const topic=e.target.closest('[data-topic]');if(topic)openLesson(topic.dataset.topic,topic.dataset.chapter);});
 $('#menuToggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#themeToggle').onclick=toggleTheme;$('#settingsTheme').onclick=toggleTheme;
 $('#startPractice').onclick=()=>startQuiz('practice');$('#startExam').onclick=()=>startQuiz('exam');
 ['bankSearch','bankFilter','bankType','bankChapter'].forEach(id=>$('#'+id).addEventListener('input',()=>{state.bankPage=0;renderBank();}));
 $('#bankList').addEventListener('change',e=>{const check=e.target.closest('.bank-select');if(!check)return;if(check.checked)state.bankSelected.add(check.value);else state.bankSelected.delete(check.value);});
 $('#bankList').addEventListener('click',e=>{const reveal=e.target.closest('[data-reveal]');if(reveal){$('#reveal-'+reveal.dataset.reveal)?.classList.toggle('show');return;}if(e.target.closest('#bankPrev')){state.bankPage=Math.max(0,state.bankPage-1);renderBank();return;}if(e.target.closest('#bankNext')){state.bankPage++;renderBank();return;}if(e.target.closest('#bankPdf')){exportBankDocument('pdf',getSelectedOrFiltered(),$('#exportMode').value);return;}if(e.target.closest('#bankDocx')){exportBankDocument('docx',getSelectedOrFiltered(),$('#exportMode').value);return;}if(e.target.closest('#practiceSelected')){const chosen=COURSE_QUESTIONS.filter(q=>state.bankSelected.has(q.id));if(!chosen.length){alert('حدد سؤالًا واحدًا على الأقل من مربعات الاختيار أولًا.');return;}setPage('practice');startQuiz('practice',chosen);return;}});
 $('#exportData').onclick=()=>{const blob=new Blob([JSON.stringify({history:state.completed,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='سجل-تقدم-منصة-الذكاء-الاصطناعي.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 $('#resetData').onclick=()=>{if(confirm('سيتم مسح سجل التقدم والمحاولات المحفوظة من هذا المتصفح. هل تريد المتابعة؟')){if(state.quiz?.timerId)clearInterval(state.quiz.timerId);state.completed=[];saveHistory();state.quiz=null;clearActive();renderDashboard();renderAnalytics();alert('تم مسح سجل التقدم المحلي.');}};
 const available=()=>{const n=currentPool('practice').length;$('#practiceAvailable').textContent=`عدد الأسئلة المطابقة للاختيارات الحالية: ${n}`;};['practiceLevel','practiceType','practiceChapter','practiceMode'].forEach(id=>$('#'+id)?.addEventListener('change',available));
 $('#examType').addEventListener('change',()=>{});
 setPage('dashboard');restoreActiveQuiz();
}
document.addEventListener('DOMContentLoaded',init,{once:true});